// Policy evaluation at ingest time
const replicationRequest = {
  tenantId: context.tenantId,
  action: 'cross-region-replicate',
  sourceRegion: context.region,
  targetRegion: config.backupRegion
};

const policyResult = policyEngine.evaluate(replicationRequest);
if (!policyResult.allowed) {
  logger.warn('Replication denied', { tenantId: context.tenantId });
  throw new PolicyViolationError('Cross-region replication not permitted for this tenant');
}

// Proceed with encrypted cross-region write
await replicateWithEncryption(context, policyResult.appliedKeys);
```

